function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic || {};

  let orderItems = [];
  let allProducts = [];
  let demandPredictions = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  const orderDateInput = container.querySelector('#order-date');
  if (orderDateInput) {
    orderDateInput.value = today;
  }

  // 明日の日付を納期の初期値に設定
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const deliveryDateInput = container.querySelector('#delivery-date');
  if (deliveryDateInput) {
    deliveryDateInput.value = tomorrow.toISOString().split('T')[0];
  }

  // 店舗データを読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    if (!storeSelect) return;

    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];

    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // 商品カテゴリを読み込み
  function loadCategories() {
    const categorySelect = container.querySelector('#category-select');
    if (!categorySelect) return;

    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const categories = [...new Set(products.map(p => p.商品カテゴリID))];

    categorySelect.innerHTML = '<option value="">全カテゴリ</option>';
    categories.forEach(categoryId => {
      if (categoryId) {
        categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId.slice(-4)}</option>`;
      }
    });
  }

  // 商品リストを更新
  function updateProductList() {
    const categorySelect = container.querySelector('#category-select');
    const productList = container.querySelector('#product-list');
    if (!categorySelect || !productList) return;

    const selectedCategory = categorySelect.value;
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];

    let filteredProducts = products.filter(p => p.有効フラグ);
    if (selectedCategory) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === selectedCategory);
    }

    allProducts = filteredProducts;

    productList.innerHTML = '';
    filteredProducts.forEach(product => {
      const row = document.createElement('tr');
      const prediction = demandPredictions.find(p => p.商品ID === product.商品ID);
      const predictedDemand = prediction ? prediction.予測需要数 : 0;

      row.innerHTML = `
        <td>${product.商品ID}</td>
        <td>${product.商品名}</td>
        <td>${product.単価}</td>
        <td>${predictedDemand}</td>
        <td><input type="number" min="0" value="0" class="order-quantity" data-product-id="${product.商品ID}"></td>
        <td><button class="add-to-order" data-product-id="${product.商品ID}">追加</button></td>
      `;
      productList.appendChild(row);
    });

    // 追加ボタンのイベントリスナーを設定
    productList.querySelectorAll('.add-to-order').forEach(button => {
      button.addEventListener('click', addToOrder);
    });
  }

  // 需要予測を実行
  async function predictDemand() {
    try {
      const storeSelect = container.querySelector('#store-select');
      const deliveryDate = container.querySelector('#delivery-date');

      if (!storeSelect?.value) {
        window.aivicNotify.error('店舗を選択してください');
        return;
      }

      if (!deliveryDate?.value) {
        window.aivicNotify.error('納期を入力してください');
        return;
      }

      // 売上データを収集
      const salesData = await collectSalesData(
        storeSelect.value,
        new Date(deliveryDate.value)
      );

      if (!salesData || salesData.length === 0) {
        window.aivicNotify.error('売上データが見つかりません');
        return;
      }

      // 商品別に分類
      const productSalesData = classifySalesDataByProduct(salesData);

      // 有効な商品データをフィルタリング
      const validProductData = filterValidProductData(productSalesData, allProducts);

      // 天候データを収集
      const weatherData = await collectWeatherData(
        storeSelect.value,
        new Date(deliveryDate.value)
      );

      // イベントデータを収集
      const eventData = await collectEventData(
        storeSelect.value,
        new Date(deliveryDate.value)
      );

      // 季節データを収集
      const seasonalData = collectSeasonalData(new Date(deliveryDate.value));

      // 相関分析を実行
      const weatherCorrelation = analyzeCorrelationSalesWeather(validProductData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(validProductData, eventData);
      const seasonalCorrelation = analyzeCorrelationSalesSeason(validProductData, seasonalData);

      // 履歴データと比較
      const historicalComparison = compareWithHistoricalData(
        validProductData,
        new Date(deliveryDate.value)
      );

      // 需要予測結果を生成
      demandPredictions = validProductData.map(productData => {
        const baseAmount = productData.平均売上数量 || 0;
        const weatherAdjustment = weatherCorrelation[productData.商品ID] || 1.0;
        const eventAdjustment = eventCorrelation[productData.商品ID] || 1.0;
        const seasonalAdjustment = seasonalCorrelation[productData.商品ID] || 1.0;
        const historicalAdjustment = historicalComparison[productData.商品ID] || 1.0;

        const predictedDemand = Math.round(
          baseAmount * weatherAdjustment * eventAdjustment * seasonalAdjustment * historicalAdjustment
        );

        return {
          商品ID: productData.商品ID,
          予測需要数: Math.max(0, predictedDemand)
        };
      });

      // 商品リストを更新して予測結果を反映
      updateProductList();

      window.aivicNotify.success('需要予測が完了しました');

    } catch (error) {
      console.error('需要予測エラー:', error);
      window.aivicNotify.error('需要予測の実行中にエラーが発生しました');
    }
  }

  // 発注リストに追加
  function addToOrder(event) {
    const productId = event.target.dataset.productId;
    const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
    const quantity = parseInt(quantityInput.value) || 0;

    if (quantity <= 0) {
      window.aivicNotify.error('数量を入力してください');
      return;
    }

    const product = allProducts.find(p => p.商品ID === productId);
    if (!product) return;

    const existingItem = orderItems.find(item => item.商品ID === productId);
    if (existingItem) {
      existingItem.発注数量 += quantity;
    } else {
      orderItems.push({
        商品ID: productId,
        商品名: product.商品名,
        単価: product.単価,
        発注数量: quantity,
        小計: product.単価 * quantity
      });
    }

    quantityInput.value = 0;
    updateOrderList();
    window.aivicNotify.success('発注リストに追加しました');
  }

  // 発注リストを更新
  function updateOrderList() {
    const orderList = container.querySelector('#order-list');
    const totalAmountElement = container.querySelector('#total-amount');

    if (!orderList) return;

    orderList.innerHTML = '';
    let totalAmount = 0;

    orderItems.forEach((item, index) => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${item.商品ID}</td>
        <td>${item.商品名}</td>
        <td>${item.単価}</td>
        <td>
          <input type="number" min="1" value="${item.発注数量}" 
                 class="update-quantity" data-index="${index}">
        </td>
        <td>${item.小計}</td>
        <td><button class="remove-item" data-index="${index}">削除</button></td>
      `;
      orderList.appendChild(row);
      totalAmount += item.小計;
    });

    if (totalAmountElement) {
      totalAmountElement.textContent = totalAmount.toLocaleString();
    }

    // 数量変更と削除のイベントリスナーを設定
    orderList.querySelectorAll('.update-quantity').forEach(input => {
      input.addEventListener('change', updateQuantity);
    });

    orderList.querySelectorAll('.remove-item').forEach(button => {
      button.addEventListener('click', removeFromOrder);
    });
  }

  // 発注数量を更新
  function updateQuantity(event) {
    const index = parseInt(event.target.dataset.index);
    const newQuantity = parseInt(event.target.value) || 1;

    if (orderItems[index]) {
      orderItems[index].発注数量 = newQuantity;
      orderItems[index].小計 = orderItems[index].単価 * newQuantity;
      updateOrderList();
    }
  }

  // 発注リストから削除
  function removeFromOrder(event) {
    const index = parseInt(event.target.dataset.index);
    orderItems.splice(index, 1);
    updateOrderList();
    window.aivicNotify.success('アイテムを削除しました');
  }

  // 発注書を保存
  async function saveOrder() {
    try {
      const storeSelect = container.querySelector('#store-select');
      const orderDate = container.querySelector('#order-date');
      const deliveryDate = container.querySelector('#delivery-date');
      const supplierSelect = container.querySelector('#supplier-select');
      const remarks = container.querySelector('#remarks');

      if (!storeSelect?.value) {
        window.aivicNotify.error('店舗を選択してください');
        return;
      }

      if (!supplierSelect?.value) {
        window.aivicNotify.error('仕入先を選択してください');
        return;
      }

      if (orderItems.length === 0) {
        window.aivicNotify.error('発注商品を追加してください');
        return;
      }

      const totalAmount = orderItems.reduce((sum, item) => sum + item.小計, 0);

      // 発注書ヘッダーを保存
      const orderHeader = {
        店舗ID: storeSelect.value,
        仕入先ID: supplierSelect.value,
        発注日: orderDate.value,
        納期: deliveryDate.value,
        合計金額: totalAmount,
        備考: remarks?.value || '',
        ステータス: '未承認'
      };

      const savedHeader = await window.aivicApi.save('発注書ヘッダ', orderHeader);

      // 発注書明細を保存
      for (const item of orderItems) {
        const orderDetail = {
          発注書ID: savedHeader.発注書ID,
          商品ID: item.商品ID,
          発注数量: item.発注数量,
          単価: item.単価,
          小計: item.小計
        };

        await window.aivicApi.save('発注書明細', orderDetail);
      }

      window.aivicNotify.success('発注書を保存しました');

      // フォームをリセット
      orderItems = [];
      updateOrderList();

    } catch (error) {
      console.error('発注書保存エラー:', error);
      window.aivicNotify.error('発注書の保存中にエラーが発生しました');
    }
  }

  // 仕入先データを読み込み
  function loadSuppliers() {
    const supplierSelect = container.querySelector('#supplier-select');
    if (!supplierSelect) return;

    const suppliers = tables.find(t => t.tableName === '仕入先マスタ')?.records || [];

    supplierSelect.innerHTML = '<option value="">仕入先を選択してください</option>';
    suppliers.forEach(supplier => {
      if (supplier.有効フラグ) {
        supplierSelect.innerHTML += `<option value="${supplier.仕入先ID}">${supplier.仕入先名}</option>`;
      }
    });
  }

  // イベントリスナーを設定
  function setupEventListeners() {
    // カテゴリ選択変更時
    const categorySelect = container.querySelector('#category-select');
    if (categorySelect) {
      categorySelect.addEventListener('change', updateProductList);
    }

    // 需要予測ボタン
    const predictButton = container.querySelector('#predict-demand');
    if (predictButton) {
      predictButton.addEventListener('click', predictDemand);
    }

    // 発注書保存ボタン
    const saveButton = container.querySelector('#save-order');
    if (saveButton) {
      saveButton.addEventListener('click', saveOrder);
    }
  }

  // 初期化処理
  function initialize() {
    loadStores();
    loadCategories();
    loadSuppliers();
    updateProductList();
    setupEventListeners();
  }

  // 初期化実行
  initialize();
}
